class Solution {
public:
    int profitableSchemes(int n, int minProfit, vector<int>& group, vector<int>& profit) {
        const int MOD = 1000000007;
        int m = group.size();
        vector<vector<long long>> dp(n + 1, vector<long long>(minProfit + 1, 0));
        dp[0][0] = 1;

        for (int i = 0; i < m; i++) {
            int g = group[i];
            int p = profit[i];
            for (int j = n; j >= g; j--) {
                for (int k = 0; k <= minProfit; k++) {
                    int newK = (k + p < minProfit) ? k + p : minProfit;
                    dp[j][newK] = (dp[j][newK] + dp[j - g][k]) % MOD;
                }
            }
        }

        long long ans = 0;
        for (int j = 0; j <= n; j++) {
            ans = (ans + dp[j][minProfit]) % MOD;
        }
        return (int)ans;
    }
};
